    val ALL_SIGNS: List<SignInfo> = LETTERS + WORDS_300

    val CATEGORIES: List<String> = listOf("All", "Letters") + WORDS_300.map { it.category }.distinct()

    fun getSignInfo(name: String): SignInfo? {
        val upper = name.uppercase()
        return ALL_SIGNS.firstOrNull { it.name.uppercase() == upper }
    }
